import{_ as d,o as e,c as o,a3 as a}from"./chunks/framework.Cgis2P7V.js";const b=JSON.parse('{"title":"Руководство по редактированию контента","description":"","frontmatter":{},"headers":[],"relativePath":"CONTENT_GUIDE.md","filePath":"CONTENT_GUIDE.md"}'),r={name:"CONTENT_GUIDE.md"};function c(i,t,s,n,h,l){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="руководство-по-редактированию-контента" tabindex="-1">Руководство по редактированию контента <a class="header-anchor" href="#руководство-по-редактированию-контента" aria-label="Permalink to &quot;Руководство по редактированию контента&quot;">​</a></h1><p>Весь пользовательский текст вынесен из Vue-компонентов. Компоненты только отображают данные.</p><h2 id="главныи-экран-календарь" tabindex="-1">Главный экран (календарь) <a class="header-anchor" href="#главныи-экран-календарь" aria-label="Permalink to &quot;Главный экран (календарь)&quot;">​</a></h2><p>Файл: <a href="./"><code>index.md</code></a></p><table tabindex="0"><thead><tr><th>Поле</th><th>Назначение</th></tr></thead><tbody><tr><td><code>eyebrow</code></td><td>Мелкая подпись над заголовком</td></tr><tr><td><code>title</code></td><td>Основной заголовок</td></tr><tr><td><code>accent</code></td><td>Акцентная часть заголовка (цветом)</td></tr><tr><td><code>description</code></td><td>Подзаголовок под заголовком</td></tr></tbody></table><h2 id="страница-«направления»" tabindex="-1">Страница «Направления» <a class="header-anchor" href="#страница-«направления»" aria-label="Permalink to &quot;Страница «Направления»&quot;">​</a></h2><p>Файл: <a href="./destinations.html"><code>destinations.md</code></a></p><table tabindex="0"><thead><tr><th>Поле</th><th>Назначение</th></tr></thead><tbody><tr><td><code>eyebrow</code></td><td>Подпись над заголовком</td></tr><tr><td><code>title</code></td><td>Заголовок страницы</td></tr></tbody></table><h2 id="страница-«авиабилеты»" tabindex="-1">Страница «Авиабилеты» <a class="header-anchor" href="#страница-«авиабилеты»" aria-label="Permalink to &quot;Страница «Авиабилеты»&quot;">​</a></h2><p>Файл: <a href="./flights.html"><code>flights.md</code></a></p><table tabindex="0"><thead><tr><th>Поле</th><th>Назначение</th></tr></thead><tbody><tr><td><code>eyebrow</code></td><td>Подпись над заголовком</td></tr><tr><td><code>title</code></td><td>Заголовок страницы</td></tr><tr><td><code>description</code></td><td>Описание под заголовком</td></tr></tbody></table><h2 id="страны-сезоны-визы-и-даивинг" tabindex="-1">Страны, сезоны, визы и дайвинг <a class="header-anchor" href="#страны-сезоны-визы-и-даивинг" aria-label="Permalink to &quot;Страны, сезоны, визы и дайвинг&quot;">​</a></h2><p>Файл: <a href="./data/destinations.json"><code>data/destinations.json</code></a></p><h3 id="массив-months" tabindex="-1">Массив <code>months</code> <a class="header-anchor" href="#массив-months" aria-label="Permalink to &quot;Массив `months`&quot;">​</a></h3><p>Названия месяцев для календаря и таблицы (12 элементов, порядок: январь → декабрь).</p><h3 id="массив-destinations" tabindex="-1">Массив <code>destinations</code> <a class="header-anchor" href="#массив-destinations" aria-label="Permalink to &quot;Массив `destinations`&quot;">​</a></h3><p>Каждое направление — объект:</p><table tabindex="0"><thead><tr><th>Поле</th><th>Назначение</th></tr></thead><tbody><tr><td><code>id</code></td><td>Уникальный идентификатор (латиница, без пробелов)</td></tr><tr><td><code>name</code></td><td>Название направления</td></tr><tr><td><code>region</code></td><td>Регион (группировка в фильтрах)</td></tr><tr><td><code>airport</code></td><td>Аэропорт</td></tr><tr><td><code>visa</code></td><td>Визовый режим: <code>Б</code> (без визы) или <code>П</code> (по прибытии)</td></tr><tr><td><code>diving</code></td><td>Уровень дайвинга: <code>Развитая</code>, <code>Есть</code> или <code>Ограниченная</code></td></tr><tr><td><code>season</code></td><td>Массив индексов месяцев (0 = январь, 11 = декабрь), когда сезон</td></tr><tr><td><code>temperature</code></td><td>Температура (строка, например <code>&quot;воздух +28°C, вода +26°C&quot;</code>) или <code>null</code></td></tr><tr><td><code>description</code></td><td>Описание направления</td></tr><tr><td><code>flights</code></td><td>Массив типичных маршрутов</td></tr><tr><td><code>budget</code></td><td>Бюджетная метка</td></tr><tr><td><code>priceFrom</code></td><td>Ориентир цены</td></tr></tbody></table><h3 id="блок-visalabels" tabindex="-1">Блок <code>visaLabels</code> <a class="header-anchor" href="#блок-visalabels" aria-label="Permalink to &quot;Блок `visaLabels`&quot;">​</a></h3><p>Подписи для визовых кодов <code>Б</code> и <code>П</code> (<code>short</code> — для бейджей, <code>long</code> — для таблицы).</p><h3 id="блок-ui" tabindex="-1">Блок <code>ui</code> <a class="header-anchor" href="#блок-ui" aria-label="Permalink to &quot;Блок `ui`&quot;">​</a></h3><p>Подписи фильтров, заголовков таблицы, плейсхолдеров и прочих элементов интерфейса. Редактируйте здесь, если нужно изменить текст кнопок и подсказок без правки кода.</p><h2 id="навигация-саита" tabindex="-1">Навигация сайта <a class="header-anchor" href="#навигация-саита" aria-label="Permalink to &quot;Навигация сайта&quot;">​</a></h2><p>Файл: <a href="./.vitepress/config.ts"><code>.vitepress/config.ts</code></a> — пункты меню и название сайта.</p><h2 id="после-правок" tabindex="-1">После правок <a class="header-anchor" href="#после-правок" aria-label="Permalink to &quot;После правок&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span></code></pre></div><p>Проверьте главную страницу, справочник направлений и страницу авиамаршрутов.</p><h2 id="проверка-визовых-условии" tabindex="-1">Проверка визовых условий <a class="header-anchor" href="#проверка-визовых-условии" aria-label="Permalink to &quot;Проверка визовых условий&quot;">​</a></h2><p>Каталог направлений в <a href="./data/destinations.json"><code>data/destinations.json</code></a> — <strong>курируемая туристическая подборка</strong> для планирования отдыха. Это не полный список стран и территорий, доступных гражданам Беларуси, и не замена официальным консульским источникам.</p><h3 id="фаил-аудита" tabindex="-1">Файл аудита <a class="header-anchor" href="#фаил-аудита" aria-label="Permalink to &quot;Файл аудита&quot;">​</a></h3><p>Таблица для поэтапной проверки виз: <a href="./data/visa-audit.csv"><code>data/visa-audit.csv</code></a>.</p><table tabindex="0"><thead><tr><th>Колонка</th><th>Назначение</th></tr></thead><tbody><tr><td><code>destination</code></td><td>Название записи в каталоге (как в <code>destinations.json</code>)</td></tr><tr><td><code>country_or_territory</code></td><td>Государство или территория для сверки правил въезда</td></tr><tr><td><code>current_visa_code</code></td><td>Текущий код в данных (<code>Б</code> или <code>П</code>) — <strong>не менять без проверки</strong></td></tr><tr><td><code>proposed_visa_type</code></td><td>Целевой тип после проверки (заполняется только по источнику)</td></tr><tr><td><code>visa_note</code></td><td>Уточнение: остров, регион, курорт и т.п.</td></tr><tr><td><code>visa_checked_at</code></td><td>Дата проверки (ISO, например <code>2026-08-08</code>)</td></tr><tr><td><code>visa_source_url</code></td><td>Ссылка на официальный источник</td></tr><tr><td><code>verification_status</code></td><td>Статус: <code>unverified</code>, <code>verified</code>, <code>disputed</code></td></tr></tbody></table><h3 id="правила-работы-с-визами" tabindex="-1">Правила работы с визами <a class="header-anchor" href="#правила-работы-с-визами" aria-label="Permalink to &quot;Правила работы с визами&quot;">​</a></h3><ol><li><strong>Статусы нельзя менять без источника.</strong> Поле <code>visa</code> в <code>destinations.json</code> и коды в интерфейсе обновляются только после сверки с официальным источником (консульство, MFA, пограничная служба принимающей страны).</li><li><strong>У каждой проверенной записи</strong> в <code>visa-audit.csv</code> должны быть заполнены <code>visa_checked_at</code> и <code>visa_source_url</code>, а <code>verification_status</code> — <code>verified</code>.</li><li><strong>Не делайте предположений</strong> в колонке <code>proposed_visa_type</code>: если источник не найден, оставляйте поле пустым и статус <code>unverified</code>.</li><li>Условия въезда зависят от срока поездки, цели, маршрута и транзита — это отражено в предупреждении на сайте, но не заменяет индивидуальную проверку перед бронированием.</li></ol>',34)])])}const u=d(r,[["render",c]]);export{b as __pageData,u as default};
